import { normalize } from 'jsr:/@std/path@^1.0.9/normalize'
import type { DefinitionBase, GenerateContextType, GeneratedValue, Stringable } from 'jsr:@skmtc/core@0.28.3'
import { TsFile } from './TsFile.ts'
import { TsImport, type ImportNameArg } from './TsImport.ts'
import { TsReExport } from './TsReExport.ts'
import { TsDefinition } from './TsDefinition.ts'
import type { TsIdentifier } from './TsIdentifier.ts'

/**
 * TypeScript's concise register vocabulary — the generator-facing form.
 *
 * Owned by this package (F10): each language defines its own concise args
 * type exposing only what the language supports, and the neutral
 * `context.register` only ever sees standardised objects. TypeScript
 * supports `reExports`; a language without them omits the field, so the
 * absence is compile-time.
 */
export type TsRegisterArgs = {
  /** Import statements to include, organized by module path. */
  imports?: Record<string, ImportNameArg[]>
  /** Re-export statements to include, organized by source module path. */
  reExports?: Record<string, TsIdentifier[]>
  /** Definition objects to include in the destination file. */
  definitions?: (DefinitionBase | undefined)[]
  /**
   * Free-form content for the destination file's neutral `custom` slot
   * ({@link FileBase.custom}) — typically a leading file banner comment (e.g.
   * a codegen header). Forwarded to `context.register`; the last
   * non-`undefined` write wins.
   */
  custom?: Stringable
}

/**
 * TypeScript's register function — the single implementation behind
 * {@link TsSnippet.register} and the projection-base veneers.
 *
 * Converts the concise import form into {@link TsImport} objects, creates
 * the destination {@link TsFile} on first write (caller-side creation — the
 * language is right here), and hands pure data to the neutral
 * `context.register`. No `generatorId`, no `Lang` object: the language is
 * this module.
 */
export const register = (
  context: GenerateContextType,
  args: TsRegisterArgs & { destinationPath: string }
): void => {
  const destinationPath = normalize(args.destinationPath)

  if (!context.getFile(destinationPath)) {
    context.addFile(new TsFile({ path: destinationPath, settings: context.settings }))
  }

  context.register({
    // Drop self-imports: a symbol exported from the destination file itself is
    // already in scope, so it is never imported. Centralising the same-file
    // check here means callers register against an export path without
    // pre-checking it (compared normalised, since `destinationPath` is too).
    imports: Object.entries(args.imports ?? {})
      .filter(([module]) => normalize(module) !== destinationPath)
      .map(([module, names]) => TsImport.fromConcise(module, names)),
    reExports: Object.entries(args.reExports ?? {})
      .filter(([, identifiers]) => identifiers.length > 0)
      .map(([module, identifiers]) => TsReExport.fromConcise(module, identifiers)),
    definitions: args.definitions,
    custom: args.custom,
    destinationPath
  })
}

/**
 * Arguments for {@link defineAndRegister}.
 */
export type TsDefineAndRegisterArgs<Value extends GeneratedValue> = {
  identifier: TsIdentifier
  value: Value
  destinationPath: string
  /** JSDoc description rendered above the declaration. */
  description?: string
  /** A `//` line comment rendered verbatim above the declaration (see {@link TsDefinition}). */
  leadingComment?: string
  noExport?: boolean
}

/**
 * Build a {@link TsDefinition} from `value` and register it at
 * `destinationPath`. The transform-level counterpart of
 * `this.defineAndRegister` — a transform (a closure with no class) imports
 * this directly; the language comes from the import, like everything else.
 *
 * No cache check — callers wrap with `context.findDefinition` first where
 * dedup is wanted (see the gen-msw accumulator pattern).
 */
export const defineAndRegister = <Value extends GeneratedValue>(
  context: GenerateContextType,
  {
    identifier,
    value,
    destinationPath,
    description,
    leadingComment,
    noExport
  }: TsDefineAndRegisterArgs<Value>
): TsDefinition<Value> => {
  const definition = new TsDefinition({
    context,
    identifier,
    value,
    description,
    leadingComment,
    noExport
  })

  register(context, { definitions: [definition], destinationPath })

  return definition
}

import type { ClientSettings } from '../types/Settings.ts'
import { CoreContext } from '../context/CoreContext.ts'
import type { ManifestContent } from '../types/Manifest.ts'
import type { GeneratorsMapContainer } from '../types/GeneratorType.ts'
import type { StackTrail } from '../context/StackTrail.ts'
import type { SkmtcDocumentInput } from '../types/SkmtcDocument.ts'
import type { AttributionState } from '../types/AttributionState.ts'
import type { Sidecar } from '../anchors/sidecar.ts'
import type { GenerationMapEntry } from '../anchors/generationMap.ts'

/**
 * Arguments for the {@link toArtifacts} transformation function.
 *
 * @example
 * ```typescript
 * const args: TransformArgs = {
 *   traceId: 'api-generation-v1',
 *   spanId: 'user-api-span',
 *   documentObject: openApiDocument,
 *   settings: {
 *     basePath: './generated',
 *     skip: { models: ['InternalModel'] }
 *   },
 *   toGeneratorConfigMap: () => myGeneratorMap,
 *   startAt: Date.now(),
 *   silent: false
 * };
 * ```
 */
type TransformArgs = {
  /** Unique identifier for the transformation trace */
  traceId: string
  /** Unique identifier for this transformation span */
  spanId: string
  /**
   * Source document. Discriminated union: an OpenAPI v3 document
   * (`{ type: 'oas', value }`) or a GraphQL SDL string / `GraphQLSchema`
   * (`{ type: 'gql', value }`). Protocol-specific parsing runs inside
   * the pipeline.
   */
  document: SkmtcDocumentInput
  /** Client settings for customizing generation behavior */
  settings: ClientSettings | undefined
  /** Optional path for writing log files */
  logsPath?: string
  /** Stack trail for distributed tracing */
  stackTrail: StackTrail
  /** Function that returns the generator configuration map */
  toGeneratorConfigMap: <EnrichmentType = undefined>() => GeneratorsMapContainer<EnrichmentType>
  /** Timestamp when transformation started */
  startAt: number
  /** Whether to suppress console output during generation */
  silent: boolean
  /**
   * Optional attribution (gen-maps) state. When set with a
   * `postPass` block, the pipeline emits sidecars + a generation-map index
   * alongside the standard artifacts. See {@link AttributionState}.
   */
  attribution?: AttributionState
  /**
   * When `true`, the result carries an `inspection` snapshot — a cycle-safe,
   * depth-bounded JSON serialization of the live `inspectedFiles` graph. Opt-in;
   * the generate/render pipeline is unaffected.
   */
  inspect?: boolean
}

/**
 * Transforms an OpenAPI v3 document into generated code artifacts and metadata.
 *
 * This is the primary function for the SKMTC transformation pipeline. It orchestrates
 * the three-phase process of parsing OpenAPI documents, generating code artifacts,
 * and rendering them to formatted files.
 *
 * The function creates a {@link CoreContext} instance and executes the full pipeline:
 * 1. **Parse**: Converts the OpenAPI document into internal OAS objects
 * 2. **Generate**: Transforms OAS objects using the provided generator configuration
 * 3. **Render**: Formats and prepares the final code artifacts
 *
 * @param args - Configuration for the transformation process
 * @returns A promise resolving to the generated artifacts and manifest
 *
 * @example Basic usage
 * ```typescript
 * import { toArtifacts } from '@skmtc/core';
 *
 * const result = await toArtifacts({
 *   traceId: 'my-api-generation',
 *   spanId: 'user-service',
 *   documentObject: myOpenApiDoc,
 *   settings: {
 *     basePath: './src/generated',
 *     skip: {
 *       models: ['InternalModel', 'DebugInfo'],
 *       operations: {
 *         '/internal/**': ['get', 'post']
 *       }
 *     }
 *   },
 *   toGeneratorConfigMap: () => ({
 *     models: modelGenerator,
 *     operations: operationGenerator
 *   }),
 *   startAt: Date.now(),
 *   silent: false
 * });
 *
 * // Access generated files
 * Object.entries(result.artifacts).forEach(([path, content]) => {
 *   console.log(`Generated: ${path}`);
 *   await Deno.writeTextFile(path, content);
 * });
 *
 * // Access generation metadata
 * console.log(`Generated ${Object.keys(result.manifest.files).length} files`);
 * console.log(`Generation took ${result.manifest.endAt - result.manifest.startAt}ms`);
 * ```
 *
 * @example Error handling
 * ```typescript
 * try {
 *   const result = await toArtifacts(transformArgs);
 *
 *   // Check for generation errors in the results
 *   const hasErrors = Object.values(result.manifest.results)
 *     .some(result => result === 'error');
 *
 *   if (hasErrors) {
 *     console.warn('Generation completed with errors');
 *   }
 * } catch (error) {
 *   console.error('Transformation failed:', error);
 * }
 * ```
 */
export const toArtifacts = ({
  traceId,
  spanId,
  document,
  settings,
  toGeneratorConfigMap,
  logsPath,
  startAt,
  silent,
  stackTrail,
  attribution,
  inspect
}: TransformArgs): {
  artifacts: Record<string, string>
  manifest: ManifestContent
  sidecars?: Record<string, Sidecar>
  generationMap?: GenerationMapEntry[]
  inspection?: unknown
} => {
  const context = new CoreContext({ spanId, logsPath, silent })

  const {
    artifacts,
    files,
    previews,
    results,
    parseIssues,
    enrichmentWarnings,
    sidecars,
    generationMap,
    inspection
  } = context.toArtifacts({
    settings,
    toGeneratorConfigMap,
    document,
    stackTrail,
    silent,
    attribution,
    inspect
  })

  const manifest: ManifestContent = {
    files,
    previews,
    traceId,
    spanId,
    results,
    parseIssues,
    enrichmentWarnings,
    deploymentId: Date.now().toString(),
    region: undefined,
    startAt,
    endAt: Date.now()
  }

  return { artifacts, manifest, sidecars, generationMap, inspection }
}

import type { GenerateContextType } from '../../context/generateTypes.ts'
import type { Lang } from '../Lang.ts'
import type { ContentSettings } from '../ContentSettings.ts'
import type { RefName } from '../../types/RefName.ts'
import type { IdentifierType } from '../IdentifierType.ts'
import type { IdentifierBase } from '../IdentifierBase.ts'
import type { GeneratedValue } from '../GeneratedValue.ts'
import type { SchemaToValueFn } from '../../types/TypeSystem.ts'

/**
 * External constructor signature for a model projection class.
 *
 * The pipeline calls `new SomeProjection(args)` with this shape; the
 * runtime base class ({@link ModelProjectionBase}) injects `generatorKey`
 * before calling `super()`.
 */
export type ModelProjectionConstructorArgs<EnrichmentType = undefined> = {
  context: GenerateContextType
  refName: RefName
  settings: ContentSettings<EnrichmentType>
  destinationPath: string
  rootRef?: RefName
}

export type WithTransformModel = {
  transformModel: (refName: RefName) => void
}

export type ToModelEnrichmentsArgs = {
  refName: RefName
  context: GenerateContextType
  /** Model variant whose enrichment should be resolved (see {@link Variant}) */
  variant: string
}

export type TransformModelArgs = {
  context: GenerateContextType
  refName: RefName
  /**
   * The model variant the engine is dispatching for this call. The
   * engine fans out one `transform` call per variant declared in the
   * consumer's `enrichments[id][refName]` block (or just `'main'`
   * when no enrichments are configured). See {@link Variant}.
   */
  variant: string
}

/**
 * Arguments a model generator's `isSupported` predicate receives at the
 * entry/dispatch boundary. The capability counterpart of
 * {@link TransformModelArgs}: it carries the resolved enrichment umbrella so
 * the predicate can gate on user config, but no schema — the predicate
 * resolves the schema itself (`context.resolveSchemaRefOnce(refName, id)`)
 * when it needs it, mirroring how `transform` works.
 */
export type IsSupportedModelArgs = {
  context: GenerateContextType
  refName: RefName
  /** Model variant being probed (see {@link Variant}) */
  variant: string
}

export type ToModelPreviewModuleArgs = {
  context: GenerateContextType
  refName: RefName
  /** Model variant the preview module describes (see {@link Variant}) */
  variant: string
}

export type ToModelMappingArgs = {
  context: GenerateContextType
  refName: RefName
  /** Model variant the mapping module describes (see {@link Variant}) */
  variant: string
}

/**
 * Arguments for a model projection's `toIdentifierName` — the pure,
 * cache-key-source half of the old `toIdentifier`.
 */
export type ToModelIdentifierNameArgs<EnrichmentType = undefined> = {
  refName: RefName
  enrichments: EnrichmentType
  /** Model variant the identifier should disambiguate (see {@link Variant}) */
  variant: string
}

export type ToModelExportPathArgs<EnrichmentType = undefined> = {
  refName: RefName
  enrichments: EnrichmentType
  /** Model variant the export path should disambiguate (see {@link Variant}) */
  variant: string
}

/**
 * Static structural type of a model projection class.
 *
 * Captures both the instance side (`new(...) => V`) and the static side
 * (`id`, `toIdentifierName`, `toIdentifierType`, `toExportPath`,
 * `toEnrichments`, `schemaToValueFn`). Passed as a type parameter to
 * `context.insertModel(...)`.
 */
export type ModelProjection<V extends GeneratedValue, EnrichmentType = undefined> = {
  prototype: V
} & {
  new ({
    context,
    refName,
    settings,
    destinationPath,
    rootRef
  }: ModelProjectionConstructorArgs<EnrichmentType>): V
  id: string
  type: 'model'
  /**
   * The projection's language — the static inherited from the language
   * snippet base the projection class is built on
   * (`toModelProjectionBase(TsSnippet, …)`). Drivers read it
   * pre-construction (cache-hit path). SPIKE (option 2 — see `notes/lang/14`).
   */
  lang: Lang
  /** Pure: the cache-key name. */
  toIdentifierName: (args: ToModelIdentifierNameArgs<EnrichmentType>) => string
  /**
   * Context-aware, overridable: the non-`name` parts of the identifier
   * (`type` / `typeName` / `exported`), derived from the schema. The engine
   * assembles `lang.toIdentifier({ name: toIdentifierName(args),
   * ...toIdentifierType(refName, context) })`.
   */
  toIdentifierType: (refName: RefName, context: GenerateContextType) => IdentifierType
  toExportPath: (args: ToModelExportPathArgs<EnrichmentType>) => string
  toEnrichments: ({ refName, context, variant }: ToModelEnrichmentsArgs) => EnrichmentType
  /**
   * Family-level capability predicate, surfaced as a static by
   * `toModelProjectionBase` (default `() => true`). The Driver probes it on
   * every `insertModel` so a peer is never handed a model it has declared
   * unsupported. Optional: a hand-rolled projection may omit it, in which
   * case it is treated as supporting every model.
   */
  isSupported?: (args: IsSupportedModelArgs) => boolean
  // deno-lint-ignore ban-types
} & Function

/**
 * A {@link ModelProjection} that can also handle **inline** (non-`$ref`)
 * schemas — the parameter type of `insertNormalizedModel`, which is the
 * only consumer of these two statics. `insertModel` (named refs only)
 * takes the plain {@link ModelProjection}, so a generator that never
 * inserts inline schemas declares neither.
 */
export type NormalizedModelProjection<V extends GeneratedValue, EnrichmentType = undefined> =
  ModelProjection<V, EnrichmentType> & {
    /** Builds the inline schema's value (the Definition body). */
    schemaToValueFn: SchemaToValueFn
    /**
     * Builds the Definition's identifier from a bare `fallbackName`. A
     * generator static; returns the neutral `IdentifierBase` (the engine
     * reads only `.name`).
     */
    createIdentifier: (name: string) => IdentifierBase
  }

