import { DefinitionBase } from 'jsr:@skmtc/core@0.28.3'
import { withDescription } from './withDescription.ts'
import { toTsKeyword, isBlockType } from './createIdentifier.ts'
import type { GeneratedValue, GenerateContextType } from 'jsr:@skmtc/core@0.28.3'
import type { TsIdentifier } from './TsIdentifier.ts'

/**
 * Constructor arguments for {@link TsDefinition}.
 */
export type TsDefinitionArgs<Value extends GeneratedValue> = {
  context: GenerateContextType
  identifier: TsIdentifier
  value: Value
  description?: string
  /**
   * A `//` line comment rendered verbatim on its own line directly above the
   * declaration (and above any JSDoc `description`). Each newline starts a
   * fresh `// ` line. Use for terse leading notes that aren't JSDoc.
   */
  leadingComment?: string
  noExport?: boolean
}

/**
 * TypeScript's concrete {@link DefinitionBase}: assembles the `export <kw>
 * Name[: Type] = value;` declaration (with an optional leading JSDoc from
 * `description`). Owns the rendering that previously lived on the engine's
 * `Definition`, byte-for-byte.
 */
export class TsDefinition<
  Value extends GeneratedValue = GeneratedValue
> extends DefinitionBase<Value> {
  /** Narrows the inherited neutral `identifier` to the concrete TS subclass
   *  (the constructor only accepts a {@link TsIdentifier}). */
  declare identifier: TsIdentifier

  description: string | undefined
  leadingComment: string | undefined
  noExport: boolean | undefined

  constructor({
    context,
    identifier,
    value,
    description,
    leadingComment,
    noExport
  }: TsDefinitionArgs<Value>) {
    super({ context, identifier, value })

    this.description = description
    this.leadingComment = leadingComment
    this.noExport = noExport
  }

  override toString(): string {
    const { type, name, typeName } = this.identifier
    const exportPrefix = this.noExport ? '' : 'export '
    const keyword = toTsKeyword(type)

    const leadingComment = this.leadingComment
      ? this.leadingComment
          .split('\n')
          .map(line => `// ${line}\n`)
          .join('')
      : ''

    // Block-form declarations (class / interface / declare namespace) take no
    // `= value` and no trailing `;` — the value carries the heritage and the
    // braced body.
    if (isBlockType(type)) {
      return (
        leadingComment +
        withDescription(`${exportPrefix}${keyword} ${name} ${this.value}\n`, {
          description: this.description
        })
      )
    }

    const identifier = typeName ? `${name}: ${typeName}` : name

    return (
      leadingComment +
      withDescription(`${exportPrefix}${keyword} ${identifier} = ${this.value};\n`, {
        description: this.description
      })
    )
  }
}

import type { Lang, GeneratedValue } from 'jsr:@skmtc/core@0.28.3'
import invariant from 'npm:tiny-invariant@1.3.3'
import { TsFile } from './TsFile.ts'
import { TsDefinition } from './TsDefinition.ts'
import { TsImport } from './TsImport.ts'
import { TsIdentifier } from './TsIdentifier.ts'
import { toTsEntityType } from './createIdentifier.ts'

/**
 * The JSDoc a definition renders above itself, when the Driver doesn't pass
 * one explicitly: a `description` carried on the projection value (an
 * accumulator exposing a resource/class-level doc). Read here so a generator
 * can annotate a definition without a dedicated engine hook.
 */
const toValueDescription = (value: GeneratedValue): string | undefined =>
  value &&
  typeof value === 'object' &&
  'description' in value &&
  typeof value.description === 'string'
    ? value.description
    : undefined

/**
 * The TypeScript {@link Lang} — carried as the static `lang` on
 * {@link import('./TsSnippet.ts').TsSnippet} and inherited by every class
 * built on it. Its only consumers are the engine's Drivers, which read it
 * off the projection class (`projection.lang`) ephemerally at each use
 * site. The engine reaches TypeScript only through these neutral
 * factories; it never names `TsFile` / `TsDefinition` / `TsImport` itself.
 */
export const typescript: Lang = {
  createFile: ({ path, settings }) => new TsFile({ path, settings }),

  toDefinition: ({ context, identifier, value, noExport, description }) => {
    // The engine holds identifiers as the neutral `IdentifierBase`; this is the
    // one boundary that narrows back to the concrete `TsIdentifier` before
    // handing it on (a foreign identifier here is a misconfiguration).
    invariant(
      identifier instanceof TsIdentifier,
      `TsDefinition needs a TsIdentifier to render '${identifier.name}', got a foreign identifier`
    )

    return new TsDefinition({
      context,
      identifier,
      value,
      noExport,
      description: description ?? toValueDescription(value)
    })
  },

  // The Driver's cross-file import of a peer Definition's identifier.
  toImport: ({ identifier, module }) => {
    invariant(
      identifier instanceof TsIdentifier,
      `TsImport needs a TsIdentifier to import '${identifier.name}', got a foreign identifier`
    )

    return TsImport.fromIdentifier(module, identifier)
  },

  // The engine's identifier-assembly seam: `name` from `toIdentifierName`,
  // the rest spread from `toIdentifierType`. Narrows the opaque `type`
  // string to this language's typed `TsEntityType`.
  toIdentifier: ({ name, type, typeName, exported }) =>
    new TsIdentifier({ name, typeName, exported, type: toTsEntityType(type) })
}

import { CodeFileBase, matchDefinitions } from 'jsr:@skmtc/core@0.28.3'
import { normalizeModuleName } from './normalizeModuleName.ts'
import type { ClientSettings, ModulePackage, DefinitionBase } from 'jsr:@skmtc/core@0.28.3'
import { TsImport } from './TsImport.ts'
import type { TsDefinition } from './TsDefinition.ts'
import { TsIdentifier } from './TsIdentifier.ts'
import type { TsEntityType } from './createIdentifier.ts'
import { TsReExport } from './TsReExport.ts'

/**
 * Constructor arguments for {@link TsFile}.
 */
export type TsFileArgs = {
  path: string
  settings: ClientSettings | undefined
}

/**
 * TypeScript's concrete code file. Owns the storage AND the dedup/merge
 * policy that the neutral {@link CodeFileBase} only declares: the definition
 * map keyed by each identifier's declaration slot
 * ({@link TsIdentifier.declarationKey}, so a `class Foo` and a `declare
 * namespace Foo` co-exist), the per-module import and re-export merges,
 * package-aware module-name normalisation, and the rendering arrangement
 * (re-exports, then imports, then definitions). Owns what the engine's `File`
 * rendered, byte-for-byte.
 */
export class TsFile extends CodeFileBase {
  /** Package configuration for cross-package module-name resolution. */
  packages: ModulePackage[] | undefined

  /**
   * Definitions keyed by each identifier's declaration slot
   * ({@link TsIdentifier.declarationKey} — `(type, name)`). A later definition
   * for a slot already taken collapses into the first; distinct slots that
   * share a name (a `class Foo` and a `declare namespace Foo`) both live here
   * — that is how TypeScript declaration merging is represented, no separate
   * collection needed. The cross-generator cache resolves a name to its
   * first-registered definition through {@link findDefinitions}.
   */
  definitions: Map<string, TsDefinition> = new Map()

  /** Imports keyed by {@link TsImport.mergeKey} (the module path). */
  imports: Map<string, TsImport> = new Map()

  /** Re-exports keyed by {@link TsReExport.mergeKey} (the module path). */
  reExports: Map<string, TsReExport> = new Map()

  constructor({ path, settings }: TsFileArgs) {
    super({ path })
    this.packages = settings?.packages
  }

  /**
   * TypeScript's duplication rule, keyed by the identifier's declaration slot
   * ({@link TsIdentifier.declarationKey} — `(type, name)`), not its rendered
   * value. The first definition for a slot wins; a later definition for the
   * same slot is the same declaration and collapses to a no-op — e.g. a
   * `columnHelper` const independently registered per table column (distinct
   * objects, same `const`), or a type alias re-registered with a different
   * value (the identifier, not the value, is the key). Definitions that share
   * a name but differ in type occupy *different* slots and both render — that
   * is TypeScript declaration merging (a `class Foo` and its `declare
   * namespace Foo`).
   */
  override addDefinition(definition: TsDefinition): void {
    const key = definition.identifier.declarationKey()

    if (!this.definitions.has(key)) {
      this.definitions.set(key, definition)
    }
  }

  /**
   * Merge imports in, collapsing any that share a `mergeKey()` (the module)
   * with an existing entry via {@link TsImport.merge}. The neutral
   * `register` calls this; the keying + merge are TypeScript's own policy.
   */
  override addImports(incoming: TsImport[]): void {
    for (const importEntry of incoming) {
      const key = importEntry.mergeKey()
      const existing = this.imports.get(key)

      this.imports.set(key, existing ? existing.merge(importEntry) : importEntry)
    }
  }

  /**
   * Merge re-exports in, collapsing any that share a `mergeKey()` (the module)
   * with an existing entry via {@link TsReExport.merge}.
   */
  override addReExports(incoming: TsReExport[]): void {
    for (const reExportEntry of incoming) {
      const key = reExportEntry.mergeKey()
      const existing = this.reExports.get(key)

      this.reExports.set(key, existing ? existing.merge(reExportEntry) : reExportEntry)
    }
  }

  /**
   * Query definitions by `name` and/or declaration `type`. No query → every
   * definition. The cross-generator cache's read seam
   * (`findDefinitions({ name })?.[0]` → the first-registered definition for a
   * name) plus the generator/test inspection surface
   * (`findDefinitions({ type: 'class' })`).
   */
  override findDefinitions(query?: {
    name?: string
    type?: TsEntityType
  }): DefinitionBase[] | undefined {
    return matchDefinitions([...this.definitions.values()], query, identifier =>
      identifier instanceof TsIdentifier ? identifier.type : undefined
    )
  }

  /**
   * Definitions in render order: primaries first (insertion order), then
   * same-name companions. A companion is a definition whose name an earlier
   * definition already claimed under a different declaration kind — e.g. a
   * `declare namespace Foo` companion of `class Foo`. TypeScript declaration
   * merging lays the companion *after* the primary (Stainless: `class … } …
   * declare namespace Foo`), so it's deferred to the end no matter when it was
   * registered. The first definition seen for a name is the primary.
   */
  #orderedDefinitions(): TsDefinition[] {
    const seenNames = new Set<string>()
    const primaries: TsDefinition[] = []
    const companions: TsDefinition[] = []

    for (const definition of this.definitions.values()) {
      if (seenNames.has(definition.identifier.name)) {
        companions.push(definition)
      } else {
        seenNames.add(definition.identifier.name)
        primaries.push(definition)
      }
    }

    return [...primaries, ...companions]
  }

  override toString(): string {
    const reExports = Array.from(this.reExports.values()).map(reExportEntry => {
      // Re-key to the package-normalised module at render time — the same
      // arrangement step the import section gets.
      const updatedModuleName = normalizeModuleName({
        destinationPath: this.path,
        exportPath: reExportEntry.module,
        packages: this.packages
      })

      return new TsReExport(updatedModuleName, reExportEntry.groups).toString()
    })

    const imports = Array.from(this.imports.values()).map(importEntry => {
      // Re-key to the package-normalised module at render time (the engine
      // normalised per-import in `File.toString`).
      const updatedModuleName = this.packages
        ? normalizeModuleName({
            destinationPath: this.path,
            exportPath: importEntry.module,
            packages: this.packages
          })
        : importEntry.module

      return new TsImport(updatedModuleName, importEntry.specifiers).toString()
    })

    const definitions = this.#orderedDefinitions()

    const body = [reExports, imports, definitions.map(definition => definition.toString())]
      .filter(section => Boolean(section.length))
      .map(section => section.join('\n'))
      .join('\n\n')

    // `custom` is the neutral leading-content slot (formerly `banner`),
    // inherited from `FileBase`; render it above the body when set.
    return this.custom ? `${this.custom}\n\n${body}` : body
  }
}

import { ImportBase } from 'jsr:@skmtc/core@0.28.3'
import { List } from './List.ts'
import type { TsIdentifier } from './TsIdentifier.ts'
import { isTypeOnly, type TsEntityType } from './createIdentifier.ts'

/**
 * The concise import form a TypeScript generator passes to `register` —
 * `'z'`, `{ User: 'IUser' }` (aliased record), or
 * `{ name, alias?, type? }` (the `type: 'type'` tag drives type-only
 * imports under `verbatimModuleSyntax`). Owned by this package: the
 * concise vocabulary is language-specific, so each `lang-*` package
 * defines its own; the neutral engine never sees it.
 */
export type ImportNameArg =
  | string
  | { [name: string]: string }
  | { name: string; alias?: string; type?: TsEntityType }

/**
 * A single imported symbol on a {@link TsImport}.
 *
 * `typeOnly` drives TypeScript's `verbatimModuleSyntax` handling — a
 * per-name `type` keyword, or a statement-level `import type { … }` when
 * every specifier is type-only. `name === '*'` (with an `alias`) is a
 * namespace import (`import * as X from '…'`).
 */
export type TsImportSpecifier = {
  name: string
  alias?: string
  typeOnly: boolean
}

const renderSpecifier = (specifier: TsImportSpecifier): string => {
  const base = specifier.alias ? `${specifier.name} as ${specifier.alias}` : specifier.name
  return specifier.typeOnly ? `type ${base}` : base
}

/**
 * Convert one concise {@link ImportNameArg} (the ergonomic form a TS
 * generator passes — `'z'`, `{ User: 'IUser' }`, `{ name, type: 'type' }`)
 * into a structured {@link TsImportSpecifier}. The concise form lives only
 * at this conversion boundary; everything downstream is structured.
 */
const toSpecifier = (argument: ImportNameArg): TsImportSpecifier => {
  if (typeof argument === 'string') {
    return { name: argument, typeOnly: false }
  }

  if ('name' in argument && typeof argument.name === 'string') {
    return { name: argument.name, alias: argument.alias, typeOnly: argument.type === 'type' }
  }

  const entry = Object.entries(argument)[0]
  if (entry === undefined || typeof entry[1] !== 'string') {
    throw new Error(`Invalid import specifier: ${JSON.stringify(argument)}`)
  }
  return { name: entry[0], alias: entry[1], typeOnly: false }
}

/**
 * TypeScript's concrete {@link ImportBase}: one module's worth of imported
 * symbols. Owns the TS import rendering (per-name `type` tags, the
 * statement-level `import type { … }` shortcut, aliases, and namespace
 * imports) via the shared {@link List} helper, so its output is identical
 * to the engine's legacy `Import`.
 */
export class TsImport extends ImportBase {
  module: string
  specifiers: TsImportSpecifier[]

  constructor(module: string, specifiers: TsImportSpecifier[]) {
    super()
    this.module = module
    this.specifiers = specifiers
  }

  /** Build from the concise `{ module: ImportNameArg[] }` form a generator passes. */
  static fromConcise(module: string, names: ImportNameArg[]): TsImport {
    return new TsImport(module, names.map(toSpecifier))
  }

  /**
   * Build the import of a single {@link TsIdentifier} from `module` — the
   * cross-file import a Driver registers when a generator references a
   * peer's Definition. The identifier's `type` drives `typeOnly` (so a type
   * identifier emits `import { type X }`).
   */
  static fromIdentifier(module: string, identifier: TsIdentifier): TsImport {
    return new TsImport(module, [{ name: identifier.name, typeOnly: isTypeOnly(identifier.type) }])
  }

  override mergeKey(): string {
    return this.module
  }

  override merge(other: ImportBase): TsImport {
    if (!(other instanceof TsImport)) {
      throw new Error(`Cannot merge a TsImport with a ${other.constructor.name}`)
    }

    // Dedup on the rendered specifier (the encoded form) — matching the
    // engine's legacy `Set<string>` dedup, where `type Foo` and `Foo` are
    // distinct entries.
    const byRendered = new Map<string, TsImportSpecifier>()
    for (const specifier of [...this.specifiers, ...other.specifiers]) {
      byRendered.set(renderSpecifier(specifier), specifier)
    }
    return new TsImport(this.module, [...byRendered.values()])
  }

  override toString(): string {
    const namespace = this.specifiers.find(specifier => specifier.name === '*')
    const named = this.specifiers.filter(specifier => specifier.name !== '*')

    // Statement-level `import type { … }` when there's no namespace and
    // every named import is type-only. The per-name `type` form is equally
    // valid; this is purely the more readable output the engine emits.
    if (
      named.length > 0 &&
      namespace === undefined &&
      named.every(specifier => specifier.typeOnly)
    ) {
      const names = named.map(specifier =>
        specifier.alias ? `${specifier.name} as ${specifier.alias}` : specifier.name
      )
      return `import type {${names.join(', ')}} from '${this.module}'`
    }

    const importObject =
      named.length > 0 || namespace === undefined
        ? List.toObject(named.map(renderSpecifier))
        : undefined
    const namespaceRender = namespace ? `* as ${namespace.alias}` : undefined
    const importItems = new List([namespaceRender, importObject], {
      separator: ', ',
      skipEmpty: true
    })

    return `import ${importItems} from '${this.module}'`
  }
}

import { extname } from 'jsr:/@std/path@^1.0.9/extname'

/**
 * The filename suffix marking a file as engine-owned, applied by the
 * engine when a projection's `toExportPath` result is stored into
 * `ContentSettings` (see `GenerateContext.to*ContentSettings`).
 * Consumers override it per project via
 * `client.json#settings.generatedSuffix`; setting it to `''` disables
 * injection entirely.
 */
export const DEFAULT_GENERATED_SUFFIX = '.generated'

/**
 * Inserts the generated-file suffix into an export path, before the
 * file extension: `@/forms/CreateForm.tsx` →
 * `@/forms/CreateForm.generated.tsx`.
 *
 * Idempotent: a path that already carries the suffix is returned
 * unchanged, so generators that predate central injection (they
 * hardcode `.generated` in `toExportPath`) keep producing byte-identical
 * paths. New generators return suffix-less paths and let the engine
 * inject.
 *
 * Rules:
 * - `suffix === ''` → path returned unchanged (project-level opt-out).
 * - A suffix without a leading dot is normalized to have one, so a
 *   config value of `"gen"` cannot false-positive on names that merely
 *   end in `gen`.
 * - The extension is the final `.`-segment (`extname`): a dotted stem
 *   keeps its dots (`user.model.tsx` → `user.model.generated.tsx`).
 *   Multi-part extensions are not special-cased (`user.d.ts` →
 *   `user.d.generated.ts`) — generated declaration files are rare and
 *   the rule stays predictable.
 * - No extension → the suffix is appended (`Makefile` →
 *   `Makefile.generated`).
 */
export const applyGeneratedSuffix = (path: string, suffix: string): string => {
  if (suffix === '') {
    return path
  }

  const dottedSuffix = suffix.startsWith('.') ? suffix : `.${suffix}`

  const extension = extname(path)

  // A trailing suffix IS the extension for extension-less names that
  // were already suffixed (`Makefile.generated`).
  if (extension === dottedSuffix) {
    return path
  }

  if (extension === '') {
    return `${path}${dottedSuffix}`
  }

  const stem = path.slice(0, -extension.length)

  if (stem.endsWith(dottedSuffix)) {
    return path
  }

  return `${stem}${dottedSuffix}${extension}`
}

/**
 * The inverse of {@link applyGeneratedSuffix}: removes the
 * generated-file suffix from an export path
 * (`@/forms/CreateForm.generated.tsx` → `@/forms/CreateForm.tsx`).
 * A path without the suffix is returned unchanged. Used by the eject
 * flow to compute the owned name of a generated file.
 */
export const removeGeneratedSuffix = (path: string, suffix: string): string => {
  if (suffix === '') {
    return path
  }

  const dottedSuffix = suffix.startsWith('.') ? suffix : `.${suffix}`

  const extension = extname(path)

  if (extension === dottedSuffix) {
    return path.slice(0, -dottedSuffix.length)
  }

  if (extension === '') {
    return path
  }

  const stem = path.slice(0, -extension.length)

  if (stem.endsWith(dottedSuffix)) {
    return `${stem.slice(0, -dottedSuffix.length)}${extension}`
  }

  return path
}

